window.HARDTRP.receive("162572",[[162573,"2026-08-16T07:58:55",9,"Начало темы.\n\n@Xerstam_4554 — Дм этой темы.",162572,null],[162583,"2026-08-16T09:39:43",2,"// Мне нужно вести трекер персонажей, поэтому я попрошу всех скинуть коротко информацию о своих персонажах в таком формате:\nИмя - ?/? ХП, ? КД\nСопротивления:\nПассивная скрытность -\nПассивная внимательность -",162572,null],[162593,"2026-08-16T09:44:36",17,"Гром - 44/44 ХП, 17 КД\nСопротивления:\nПассивная скрытность: 13 (если 10+ловкость)\nПассивная внимательность: 14",162572,null],[162594,"2026-08-16T09:44:47",2,"1. Гром - 59/44 ХП, 17 КД\nДоспех агатиса - 15\nПассивная скрытность: 13\nПассивная внимательность: 14\n\n2. Орочи - 38/38 ХП, 15 КД\nИммунитет: яд\nПассивная скрытность: 13\nПассивная внимательность: 14\n\n\n3. Азраэль - 7/12 ХП 17 КД\nСопротивление к : излучению , некротическая энергия \nПас. Скр 10\nПас. Муд 10\n\n\n4. Волшебник - 20/20 ХП, 12 КД",162572,null],[162600,"2026-08-16T09:52:59",31,"Орочи - 38/38 ХП, 15 КД\nСокротивления: иммунитет к яду\nПассивная скрытность: 13 (если я ее верное понимаю)\nПассивная внимательность: 14",162572,null],[162601,"2026-08-16T09:53:15",2,"#GM\nВы находитесь в небольшом городе Тенебрис, у окраин которого зима никогда не заканчивается. Уже неделю местные шепчутся о странном свечении в старых шахтах, а по ночам из-под земли доносится вой, похожий на человеческий крик. Трое стражников, отправленных на разведку не вернулись. В их числе был придворный чародей. Гильдия искателей приключений получила срочный заказ от герцога: разобраться с аномалией, пока она не вышла за пределы шахт.\n\nСегодня утром вы получили это задание лично от посыльного герцога. Сумма щедрая — по 200 золотых каждому, плюс любые артефакты, найденные внутри. Герцог посоветовал взять тёплую одежду и быть осторожнее — четвёртую группу он отправлять не собирается. Перед тем как отправиться, у вас есть время, чтобы запастись необходимым снаряжением перед вылазкой в подземелье... Ведь она может стать последней в вашей жизни.",162572,null],[162602,"2026-08-16T09:55:10",2,"@QURTZZ @dunchev @Shadiq_an",162572,null],[162603,"2026-08-16T09:57:16",31,"Пока не могу, извините. Ехал по делам и машина гавкнулась. Буду ковырять//",162572,null],[162606,"2026-08-16T10:04:53",26,"Тут//",162602,null],[162607,"2026-08-16T10:10:21",26,"Азраэль -12/12 хр 17 КД\nСопротивление к : излучению , некротическая энергия \nПас. Скр 10\nПас. Муд 10",162594,null],[162627,"2026-08-16T14:53:34",2,"// Жду постов от вас",162572,null],[162628,"2026-08-16T14:54:01",2,"@QURTZZ @dunchev @Shadiq_an",162572,null],[162629,"2026-08-16T15:05:18",26,"А ряльно//",162572,null],[162630,"2026-08-16T15:07:47",17,"Гром Камнелом коренастый дварф в чешуйчатой броне зашёл к продавцу разной всячины.\n\n— Хозяин. Теплую накидку на меху. Факелы десяток. Непромокаемые трусы. И...есть у тебя сигары?",162572,null],[162637,"2026-08-16T15:15:58",2,"Гром зашёл в небольшую лавку, из которой доносился неприятный запах неизвестного происхождения. С виду это было обычное жилище, забитое шкафами. За стойкой сидела пожилая эльфийка с длинными седыми волосами по самые плечи. Она что-то плела. Грому пришлось подождать секунд 30, прежде чем она наконец отвлеклась и подошла к шкафам. Пошарившись по ним, бабулька протянула ему то, чего он хотел, в том числе пачку сигар. \n-Две золотых.",162630,null],[162638,"2026-08-16T15:17:22",26,"*Азраэль достаточно высокий (190) Аасимар в кольчуге и с двумя мечами на поясе идет по снежному городу в поисках магазинчика где можно прикупить одежды и заходит вслед за Громом*\n\n— Aureus il Lumen Exaltatus Sol (на некбожительском)\n— здравствуйте  имеется одежка по теплее?(это уже на общем)",162572,null],[162639,"2026-08-16T15:19:36",17,"— Эльфка. А есть немножко... Дымной травки?",162637,null],[162640,"2026-08-16T15:20:27",17,"— Опа. Куда собрался воин? Тоже небось по этому заказу? \n\nПоказывает листовку с заданием",162638,null],[162641,"2026-08-16T15:23:13",2,"Старуха не поняла ни слова, ведь ей не был известен этот язык. Она не ответила ничего.  Торговка протянула высушенный ароматный пучок травы.",162638,null],[162643,"2026-08-16T15:25:25",26,"*кивнул*\n— я Азраэль\n *протянул руку*",162640,null],[162644,"2026-08-16T15:31:13",26,"— таааак есть одежда и в какую цену? *повернул голову уже в сторону продавщицы*",162641,null],[162649,"2026-08-16T15:33:54",17,"— Я Гром. \n\nКрепко пожал руку и оскалился в широкой улыбке",162643,null],[162650,"2026-08-16T15:34:13",17,"/ Дымная трава это наркота если что",162641,null],[162652,"2026-08-16T15:36:14",26,"*рукопожатие у Ахраэля тоже не простое видно что привык к дварфским рукопожатиям* \n— знаете , Гром, вы напомнили мне мое наставника может вым знаком Торн? (Thorn)",162649,null],[162653,"2026-08-16T15:37:34",17,"— Прости дружище, нет не слышал. Меня очень рано выпнули из общины и я скитался среди простого люда в Аннеже. Так и вступил на дорогу приключений.",162652,null],[162657,"2026-08-16T15:45:50",26,"— а сколько вышла вам тёплая одежда? \n*уже чутка устал ждать ответа от продавщицы*",162653,null],[162659,"2026-08-16T15:49:36",2,"// она тебе не такую далу",162650,null],[162661,"2026-08-16T15:52:12",2,"// я там чуть-чуть с ценами обсчитался, извиняюсь, что так вышло. Ещё 5 зм за шубу",162630,null],[162662,"2026-08-16T15:52:58",2,"Старуха достала шубу из соболиной шкуры и протянула своими дряхлыми пальцами. \n-5 золотых.",162644,null],[162663,"2026-08-16T16:03:18",26,"*положил на прилавок 5 золотых сняв кольчугу одел ее поверх  льняной рухи* \n— вот что что а вот шить эльфы могу (сказал на дварфском Грому) \n*после же одел кольчугу и накидку ордена поверх*\n— чтож теперь не замерзнем",162572,null],[162664,"2026-08-16T16:13:54",31,"Орочи, шестиметровый нага, даже не пытается зайти в таверну, значит что не поместится, были прецеденты. Просовывет голову в окно и спрашивает:\n\n- ечть ли тут хоть что-то, что я могу надеть для того чтобы не превратился в сосульку? А то чувствую, это задание станет для меня последним",162572,null],[162665,"2026-08-16T16:14:59",31,"Извините за ожидание парни, весь день провёл под машиной и завтра видимо тоже вечером под ней буду лежать. Ломаться в воскресенье это так себе идея, хрен найдешь запчасти//",162572,null],[162668,"2026-08-16T16:16:03",26,"*посмотрел в проход и слегка удивился *\n— вы тоже по заданию в пещере?",162572,null],[162669,"2026-08-16T16:16:56",31,"- да. Надеюсь там будет хоть чуток меньше этого проклятого ветра, он меня в сон вгоняет\n\n//отыгрываю теплолюбивость наги//",162668,null],[162670,"2026-08-16T16:20:02",26,"— поговаривают там ещё холодней \n*поправил все и стал ожидать указаний или каких либо диалогов*",162572,null],[162671,"2026-08-16T16:24:40",31,"- ммм, ладно, я приму это как подобает воину - с достоинством",162572,null],[162673,"2026-08-16T16:32:31",2,"Старуха замерла, увидев нагу. Она шёпотом что-то прошептала, молясь старым богам. Эльфийка вошла в кладовку и вытащила оттуда огромную шкуру совомеда. Такая шуба будет по размеру Орочи, а стоит она 30 золотых. Местами виднелись царапины, кое где даже дырки. Возможно, если бы она была в идеальном состоянии, то стоила бы ещё дороже.",162664,null],[162676,"2026-08-16T16:34:07",31,"- о, благодарю вас добрая госпожа, это точ то мне нужно. Вот деньги\n\n*передаю деньги и с кайфом заворачиваюсь в теплую шубу*",162572,null],[162678,"2026-08-16T16:40:50",2,"Внезапно раздался стук. В лавку вошёл худой запыхавшийся юноша. Он был одет в кожаный доспех, на поясе у него находился кинжал. Отдышавшись, парень сказал. \n\n-Я вижу, вы собираетесь вниз. В ту пещеру... \nОн смотрит на их покупки и качает головой.\n-Я провожу вас до входа. Это лучшее, что я могу для вас сделать. Я уже провожал туда двоих. Никто не вернулся. Но я не хочу, чтобы вы шли туда одни, потому что даже путь до двери там кажется бесконечным.\nОн замолкает и достаёт из-за пазухи завёрнутый в ткань предмет. Это старый амулет из тёмного металла, холодный на ощупь.\n-Это принадлежало одному из тех, кто пошёл туда. Последний из его вещей. Я не знаю, поможет ли он вам. Но когда я его ношу, мне кажется, что я слышу его голос. Он говорит: \"Не стой на месте. Двигайся. Холод ждёт, когда ты остановишься.\".",162572,null],[162679,"2026-08-16T16:41:05",2,"@Shadiq_an @QURTZZ @dunchev",162572,null],[162680,"2026-08-16T16:42:24",31,"- движение - жизнь. И жизнь в движении, понятно. Расскажешь о тех кто был до нас и о их уровне подготовки. Да и в целом, что мы должны знать?",162572,null],[162682,"2026-08-16T16:45:38",2,"-Я понятия не имею, что творится за дверью этих катакомб. Но там невероятно холодно. Я проводил туда двух ребят. Эх... Славные были парни. Одного звали Джеймс, он, кажется, был сыном нашего кузнеца. Тот теперь совсем из дома не выходит. Крепкий был юноша, с мечом хорошо обращался. Наверное, умер от холода. А второго, кажется, звали Уильям? Не знал его, не могу ничего сказать о нём. Поговаривают, что он маг. Магия — опасная штука и несёт одни несчастья, не хочу связываться с этими колдунами.",162680,null],[162683,"2026-08-16T16:47:05",26,"*стоически кивал, после же глянул на более опытных товарищей* \n\n— так-с господа что у нас есть по снаряжению?",162572,null],[162684,"2026-08-16T16:49:12",31,"- ну, у меня есть только мои руки, тело и теперь еще и шуба. Ну и запас зелий здоровья, штук 10 вроде",162683,null],[162686,"2026-08-16T16:50:01",2,"// я кстати разрешаю зелья бонусным действием пить",162684,null],[162688,"2026-08-16T16:52:33",26,"— 1 зелье здоровья, еще есть 9 копьев, спальник, рационы , веревка 50 футов, факелы и свечи тоже есть короче имеется много чего",162572,null],[162689,"2026-08-16T16:55:03",26,"*чуть еще подумав добавил* \n— я еще конечно учусь путю паладина , но уже могу вполне исцелять людей",162572,null],[162690,"2026-08-16T16:58:39",17,"— У меня есть древняя магия и этот волшебный меч.\n\nДварф снял с пояса рукоять без лезвия. \n\nНажал на ней какую-то кнопку и вдруг из этой рукояти поднялся клинок из чистой молнии. Стало светло.\n\nЗвук был БЗЗЗЗЗЗЗ\n\n— От, так вот. Не пропадем.",162572,null],[162692,"2026-08-16T16:59:24",17,"/ мастер это солнечный клинок",162572,null],[162694,"2026-08-16T17:00:04",17,"/ по механике предмета. Я его просто рескин сделал для образа",162572,null],[162698,"2026-08-16T17:01:06",17,"/ да вы чё угораете",162572,null],[162699,"2026-08-16T17:01:08",17,"/ просто нарративный рескин",162572,null],[162702,"2026-08-16T17:02:20",17,"Дварф тыкнул кнопочку и лезвие тут же обратно скрылось в рукояти",162572,null],[162703,"2026-08-16T17:02:25",17,"Бзззз",162572,null],[162705,"2026-08-16T17:02:46",26,"//хыхых брейкин был момент",162572,null],[162706,"2026-08-16T17:02:59",17,"/ ю гад демн Райт",162572,null],[162707,"2026-08-16T17:03:00",26,"— Чтож я поражен *чуть похлопал*",162572,null],[162708,"2026-08-16T17:03:06",31,"- о, огненный меч. Хоть не замерзнем",162572,null],[162709,"2026-08-16T17:03:14",26,"ГАЙДЗИНЫ ОНЕТОНЕТ ОПЯТЬ УЛИТКИ//",162706,null],[162711,"2026-08-16T17:05:02",26,"— тааак мы выдвигаемся? Помоему наш проводник чу-чуть и окочуриться на морозе \n*посмотрел с некоторой жалостью на паренька*",162572,null],[162713,"2026-08-16T17:06:47",17,"— Парень, бери амулет тогда ты.\n\nКивнул на паладина",162572,null],[162714,"2026-08-16T17:07:21",26,"— Я? И что за амулет?",162572,null],[162715,"2026-08-16T17:07:30",2,"-Я лишь провожу вас до ворот, в последний путь... Сам я туда не пойду. Надеюсь, вы вернётесь оттуда живыми.",162711,null],[162716,"2026-08-16T17:08:08",26,"—А да хорошо я возьму его",162572,null],[162717,"2026-08-16T17:11:15",26,"— ну-ну какой же последний путь? Будем верить что солнце взойдет и настанет благодать \n*взял амулет и встал возле прохода ожидая когда отправимся*",162572,null],[162725,"2026-08-16T17:19:36",26,"//тонкое продвижение фанатичности через фразы",162717,null],[162727,"2026-08-16T17:21:16",31,"Ползём на встречу приключениям",162572,null],[162728,"2026-08-16T17:21:30",17,"Дварф закуривает сигару",162572,null],[162729,"2026-08-16T17:22:23",17,"Достает кружку она совершенно пустая \n\nНакрывает ладошкоц и когда убивает со дна начинает подниматься пенное\n\nВкусный запах темного хмельного пива",162572,null],[162730,"2026-08-16T17:22:40",17,"— Ваше здоровье товарищи!",162572,null],[162731,"2026-08-16T17:22:48",17,"Осушает ее до дна",162572,null],[162733,"2026-08-16T17:24:45",31,"- заранее утепляешься? Разумно",162572,null],[162735,"2026-08-16T17:26:50",2,"Группа выходит на улицу. В тёплых шубах холод совсем не ощущался, но надолго ли это? Парень посинел и ничего не говорил, не обратил внимания даже на то, что из ниоткуда появилось пиво. Он провёл вас по узким дорогам вниз по горе и остановился у входа в огромную пещеру. \n-Дальше вы сами. Постарайтесь вернуться живыми. Хотя, о чём это я. Никто не возвращается отсюда живым. Вы не первые и не последние. \nВздохнув, он ушёл.",162730,null],[162737,"2026-08-16T17:27:50",26,"— Лед лёд лед *ступал сапогами по льду пытаясь не скользить*",162572,null],[162738,"2026-08-16T17:29:21",31,"Скольжу по льду, стараясь не думать о том как эта мерзкая субстанция может повредить мое брюхо",162572,null],[162739,"2026-08-16T17:34:02",2,"Спускаясь вниз по скользким пещерным коридорам, вы наконец натыкаетесь на огромное каменное строение. Видимо, это и была лаборатория алхимика. Место тумана там большие комнаты, их размер намного больше, чем на карте. Куда группа двинется? Температура здесь аномально низкая. Возможно, -40°, -50°,  или даже ниже! Куртки, может, и снизят вред от холода, но всё равно придётся периодически делать остановки, чтобы развести костёр и согреться.",162572,null],[162740,"2026-08-16T17:36:06",26,"— ну и холодрыга у меня волосы к шлему уже липнут, но он хоть немного задерживает мое тепло от дыхания",162572,null],[162741,"2026-08-16T17:37:33",26,"Не против если сделаем перерыв до завтра?//",162572,null],[162742,"2026-08-16T17:37:50",26,"Просто чувствую что скоро чето будет , а в этот момент я начну уже все//",162572,null],[162743,"2026-08-16T17:37:55",31,"Я не против/",162741,null],[162744,"2026-08-16T17:38:10",31,"Извините что всех сегодня задержал//",162572,null],[162745,"2026-08-16T17:38:11",2,"// как хотите",162741,null],[162746,"2026-08-16T17:39:05",26,"Да с кем не бывает//",162744,null],[162752,"2026-08-16T18:07:08",17,"/ Да я тоже щас через час бы только освободился дел дофига в выходные",162572,null],[162805,"2026-08-16T20:48:01",2,"// @Pro551o завтра впишу тебя",162572,null],[163301,"2026-08-17T08:22:06",2,"Пробираясь по тёмным коридорам, внезапно вы слышите грохот. Звук доносился из входа в пещеру. Оглянувшись и пройдя немного назад, вы увидели, что из-под завалов выглядывает чья-то рука, а после и голова. Неизвестный выбрался и отдышался. Это был последний, опоздавший авантюрист. Вход в пещеру завалило, и теперь выйти из неё через это место не представлялось возможным.",162572,null],[163302,"2026-08-17T08:22:22",2,"@Pro551o @Shadiq_an @dunchev @QURTZZ",162572,null],[163303,"2026-08-17T08:23:45",31,"- ты успел вовремя, дружище, надеюсь, что ты не зря спешил",162572,null],[163304,"2026-08-17T08:29:16",26,"Тут//",163302,null],[163305,"2026-08-17T08:30:06",26,"— Мг вход завалило \n*смотрел и на новое лицо* \n— о еще участники",162572,null],[163306,"2026-08-17T08:34:41",26,"Имея анемию крайне легко понимать состояние перса в холоде//",162572,null],[163307,"2026-08-17T08:34:50",26,"У меня ноги и руки как у трупа хотя дома тепло//",162572,null],[163309,"2026-08-17T08:56:54",17,"— Теперь вы тут заперты, разбирать завал неделю, атк что топаем дальше. Может есть еще выходы из этих ледяных катакомб. А так товарищи думаю все понимают, что мы в ДЭРМЭ",162572,null],[163310,"2026-08-17T08:57:07",17,"Дварф подошел и вытащил опоздавшего",162572,null],[163311,"2026-08-17T08:57:14",17,"— КТо такой будешь опоздун?",162572,null],[163348,"2026-08-17T09:40:23",26,"— теперь уж точно в полном сборе \n*топтался на месте сохраняя тепло* \n— хммм , может проверить мое чувство?",162572,null],[163367,"2026-08-17T09:52:41",2,"@Pro551o",162572,null],[163386,"2026-08-17T10:22:59",26,"Хочу божественное чувство использовать //",162572,null],[163390,"2026-08-17T10:24:56",2,"В пределах 60 футов не было никого, кого могла бы засечь эта способность. Неудивительно, ведь группа находилась у самого входа и ещё не решила куда пойти.",163386,null],[163401,"2026-08-17T10:28:20",26,"— Мммммм, хорошая новость) , с ходу нам пока ничего не угрожает божественное чувство подсказывает мне что здесь никого нет помимо нас ну их тех кого мог бы засечь",162572,null],[163409,"2026-08-17T10:37:06",17,"Дварф отправился дальше \n\nБЗЗЗ меч загорелся и его свет освещал ярко всё вокруг\n\nОН осматривал проход, чтобы понять варианты дальнейшего пути",162572,null],[163411,"2026-08-17T10:40:41",26,"*шел следом за дварфом держа руки на рукоятях мечей*",162572,null],[163413,"2026-08-17T10:42:04",2,"// Я напоминаю, что данж представляет из себя вот такое помещение с огромными комнатами. Вы ничего не знаете о комнатах, выбирайте куда идти",162572,null],[163417,"2026-08-17T10:42:28",2,"// Там темно, вы не видите абсолютно ничего, кроме коридоров",162572,null],[163419,"2026-08-17T10:43:04",17,"/Обожаю данжен кроулы..............",162572,null],[163421,"2026-08-17T10:43:16",17,"/Почему не видим если свет есть?, или типо заранее не видим",162572,null],[163422,"2026-08-17T10:43:35",17,"— Дварфы налево не ходят! \n\nИ Гром заходит в правую компану от входа",162572,null],[163425,"2026-08-17T10:44:19",31,"- и многое теряют. \n\nОрочи вполголоса прокомментировал слова дворфа и ползёт следом",162572,null],[163433,"2026-08-17T10:47:06",26,"Может мне тоже свет задействовать?.. *зашел предпоследним*",162572,null],[163435,"2026-08-17T10:47:30",17,"Дварф покрывается ледяной коркой",162572,null],[163436,"2026-08-17T10:47:38",17,"/Доспех агатиса 3 ячейкой +15 временных хитов",162572,null],[163437,"2026-08-17T10:48:55",2,"// комнаты не такого размера, как на рисунке. Считай, что это квадраты по 250+ метров. Вы видите лишь длинные коридоры, которые ведут в эти комнаты",163421,null],[163438,"2026-08-17T10:50:05",26,"— Коридоры коридоры коридоры. Что-нибудь интересное видит кто?",162572,null],[163439,"2026-08-17T10:50:21",17,"— Нет, холод и камень",162572,null],[163440,"2026-08-17T10:50:28",17,"/r +4 Внимание",162572,null],[163444,"2026-08-17T10:55:46",2,"Группа продвигается по коридору и наконец добирается до просторного зала, конца которому не видно. Возможно, кто-то из вас держит в руках факела или обладает тёмным зрением, поэтому часть комнаты была видна. Сначала в глаза не бросалось ничего особенного, но вскоре вы наткнулись на странные надписи на стене. Перед вами были четыре руны и четыре пьедестала. \n\nНа стене:\n❄ ❖ ☽ 🔥\nПеред ней четыре пьедестала с переставляемыми рунами. Текст на стене гласил:\n«Холод рождается из воды.\nВода следует за луной.\nОгонь уничтожает холод.\nСвет остаётся последним.»",162572,null],[163445,"2026-08-17T10:56:31",2,"@dunchev @QURTZZ @Shadiq_an @Pro551o",162572,null],[163446,"2026-08-17T10:56:43",17,"Дварф почесал подбородок освещая мечом молний стенку с надписями",162572,null],[163447,"2026-08-17T10:57:01",17,"— Ну дураку понятно надо активировать пъедесталы в нужной последовательности",162572,null],[163448,"2026-08-17T10:57:13",17,"Пошел смотреть пъедесталы они могут двигаться? Что на них",162572,null],[163449,"2026-08-17T10:58:07",2,"// 4 пьедестала, на каждом руна. Руны можно переставлять",163448,null],[163452,"2026-08-17T10:59:57",26,"— Хммммм руны руны руны. *Подошел поближе и стал рассматривать вдруг знакомая анцдеться *\n— Теекс по идее тут есть руны озночающие то что было в тексте",162572,null],[163453,"2026-08-17T11:00:32",2,"// вот такие руны",163444,null],[163454,"2026-08-17T11:00:40",2,"// по одной на каждом пьедестале",162572,null],[163455,"2026-08-17T11:01:25",26,"— Так ну снежинка это холод, огонек это огонь луна это луна , а вот этот четырех угольник должно быть свет? *стоял вдуплял на пару с громом*",162572,null],[163465,"2026-08-17T11:06:44",31,"- ну насколько я могу понять, наша задача расставить руны в последовательности согласно стиху. Но они вроде и так расставлены верно",162572,null],[163466,"2026-08-17T11:06:46",26,"*начал крайние потуги размышлений при помощи своей извилины (и той прямой) в попытке сопоставить все*\n— начнем с самого простого! *взял руну света и поставил на последний пьедестал*",162572,null],[163469,"2026-08-17T11:07:26",17,"— Нет, не верно ты чего",163465,null],[163470,"2026-08-17T11:07:37",31,"Огонь третьим должен быть, за ним свет",163466,null],[163471,"2026-08-17T11:07:39",17,"— Огонь в конце это верно",162572,null],[163472,"2026-08-17T11:08:03",2,"Комната не была исследована полностью. Вы прошли лишь малую её часть. Возможно, стоит поискать подсказки в другом месте?",162572,null],[163473,"2026-08-17T11:08:08",17,"— Так у нас нет света отдельно, это вода я думаю. Огонь тут и есть свет",162572,null],[163474,"2026-08-17T11:08:42",17,"Дварф внимательно присматривается к руне ❖ чтобы понять её смысл",162572,null],[163476,"2026-08-17T11:08:53",17,"/r -1 История",162572,null],[163479,"2026-08-17T11:09:58",2,"Ты понимаешь, что эта руна, вероятно, означает \"свет\".",163474,null],[163480,"2026-08-17T11:10:08",31,"/roll d20+4 на внимательность, медленно проползаю вдоль других стен и ищу еще какие то знания",162572,null],[163482,"2026-08-17T11:10:23",17,"— Хотя да, это руна света",162572,null],[163483,"2026-08-17T11:11:14",17,"— Вода следует за луной, руны для нее отдельной нет так что после луны сразу лёд, потом огонь и потом свет",162572,null],[163484,"2026-08-17T11:11:20",17,"— Я думаю я разгадал",162572,null],[163485,"2026-08-17T11:11:33",17,"Дварф пошел ставить руны ☽  ❄️  🔥  ❖",162572,null],[163487,"2026-08-17T11:15:38",2,"Орочи прошёл вперёд и заметил, что в центре зала пол обрывается. Дальше находится замерзшая вода. Лёд выглядит хрупким. В конце этого замерзшего участка стоит пятый пьедестал, на котором лежит руна в виде капли (\"💧\"). Пьедестал выглядит лёгким, его можно поднять и перенести в основной ряд, чтобы поставить рядом с остальными пьедесталами. Проблема в том, чтобы пересечь этот хрупкий лёд — он может проломиться, и Орочи окажется в ледяной воде.",162572,null],[163489,"2026-08-17T11:16:22",2,"// не пишите пока",162572,null],[163493,"2026-08-17T11:20:25",2,"Дварф расставляет 4 руны. На мгновение ничего не происходит. Затем руны начинают слабо пульсировать, и из трещин в стенах слышится скрежет. Это был не тот порядок. Из темноты медленно выходят два скелета с колбами в руках. Они одеты в чёрные мантии. Руны никуда не исчезли.",163485,null],[163494,"2026-08-17T11:21:06",31,"инициатива?/",162572,null],[163497,"2026-08-17T11:22:28",2,"// да, я щас только занят немного, киньте пока",162572,null],[163500,"2026-08-17T11:23:24",17,"/r +3 Ини Гром",162572,null],[163502,"2026-08-17T11:23:48",17,"— Блятство! А я вам говорил не спешите! Или не говорил?",162572,null],[163503,"2026-08-17T11:23:56",26,"/r 1d20",162572,null],[163504,"2026-08-17T11:23:57",17,"Он рассмеялся и приготовился к бою",162572,null],[163507,"2026-08-17T11:24:41",26,"*достал мечи из ножен* \n— после скелетов понесем 5 пьедестал!",162572,null],[163509,"2026-08-17T11:25:38",31,"/roll d20+3 инициатива Орочи",162572,null],[163511,"2026-08-17T11:26:06",31,"не болтаю, просто готовлюсь к бою",162572,null],[163526,"2026-08-17T11:39:19",2,"/roll d20+1",162572,null],[163531,"2026-08-17T11:40:20",2,"Ждём про?",162572,null],[163532,"2026-08-17T11:41:15",31,"да вот хз. должен был уже проклюнутсяне кажется//",162572,null],[163534,"2026-08-17T11:41:54",26,"Он судя по всему больше к вечеру активен. Ну судя по тому как у нас игры проходили когда был дм//",162572,null],[163537,"2026-08-17T11:43:47",2,"// он час назад активен был",163534,null],[163544,"2026-08-17T11:51:16",31,"тегни его, если не пидет за полчаса, то без него бьемся, его скелеты отрубили походя//",163537,null],[163545,"2026-08-17T11:51:28",2,"@Pro551o",162572,null],[163546,"2026-08-17T11:51:49",2,"// хорошо, это всё равно не главный энкаунтер",163544,null],[163617,"2026-08-17T12:28:25",2,"// @QURTZZ @Shadiq_an @dunchev будем ждать дальше?",162572,null],[163618,"2026-08-17T12:28:41",26,"Без разницы//",163617,null],[163619,"2026-08-17T12:28:49",26,"Можем подождать если захотят//",162572,null],[163624,"2026-08-17T12:30:22",31,"давайте уже скелетов ломать//",162572,null],[163625,"2026-08-17T12:30:28",31,"или они нас/",162572,null],[163633,"2026-08-17T12:34:33",23,"шо",163545,null],[163634,"2026-08-17T12:34:51",26,"Игра тут //",163633,null],[163636,"2026-08-17T12:34:58",26,"И скелеты 2 штука//",162572,null],[163642,"2026-08-17T12:36:26",23,"мда одни и те же грабли//",162572,null],[163643,"2026-08-17T12:36:36",23,"я занят без меня видимо///",162572,null],[163645,"2026-08-17T12:37:03",23,"сори я шас а перерыве на обед отвечаю",162572,null],[163699,"2026-08-17T12:57:43",2,"Тогда ход скелета",162572,null],[163704,"2026-08-17T12:59:05",2,"Волшебник споткнулся, и его мантию придавило камнем. Он не может выбраться, а фокусировка выпала из его рук, до неё не дотянуться. Один из скелетов кидает склянки в Азраэля и бежит в сторону выхода из комнаты.",162572,null],[163705,"2026-08-17T12:59:17",2,"/roll d20+4",162572,null],[163712,"2026-08-17T13:00:09",2,"/roll d8+2",162572,null],[163715,"2026-08-17T13:00:24",2,"// @Shadiq_an у тебя будут какие-то реакции?",162572,null],[163718,"2026-08-17T13:01:22",17,"/ Решил сразу похоронить первачка, жестко",162572,null],[163720,"2026-08-17T13:02:02",26,"Нету никаких ещё :')//",163715,null],[163722,"2026-08-17T13:02:27",2,"Одна из склянок разбивается у ног Азраэля, а вторая попала в цель и оставила едкий след на его коже, даже шкура не спасла — правый рукав теперь частично подожжён. Паладин чувствует резкую боль в плече. Ход Орочи",162572,null],[163723,"2026-08-17T13:02:31",2,"@QURTZZ",162572,null],[163728,"2026-08-17T13:03:56",31,"далеко мне до того скелета что напал на палладина?/",162572,null],[163732,"2026-08-17T13:04:21",2,"40 футов",163728,null],[163735,"2026-08-17T13:05:20",31,"тогда я быстро перемещаюсь туда и наношу удар",162572,null],[163739,"2026-08-17T13:06:29",26,"А наложение рук действие или доп? //",162572,null],[163740,"2026-08-17T13:06:43",26,"Типо по какой редакции 14 или 24 играем//",162572,null],[163741,"2026-08-17T13:06:48",2,"// действие",163739,null],[163743,"2026-08-17T13:07:00",31,"/roll d20+7 бью скелета телом с разбега. Если что, мод считаю как 3 от ловкости, 3 от бонуса мастерства и 1 от обмоток на +1",162572,null],[163745,"2026-08-17T13:07:16",31,"10 это мимо?/",162572,null],[163746,"2026-08-17T13:07:46",2,"Орочи бросается на убегающего скелета, но тот уклоняется от массивной наги. Ход Грома\n@dunchev",162572,null],[163748,"2026-08-17T13:08:41",17,"Гром видя как убегают скелеты бежит и во вспышке молний телепортируется перед ними закрывая выход из комнаты собой\n\n— КУДА СОБРАЛИСЬ, СУКИ?!\n\n/Туманный шаг",162572,null],[163751,"2026-08-17T13:09:05",17,"/ Основным действием удар громовым клинком или зеленым",162572,null],[163752,"2026-08-17T13:09:10",17,"/Скелеты друг от друга в 5?",162572,null],[163755,"2026-08-17T13:09:53",2,"// нет, один из них убежал и стоит рядом с Орочи в 40 футах отсюда. Другой находится рядом с остальными",163752,null],[163757,"2026-08-17T13:10:35",17,"/ Который бежал орочи рядом с ним?",163755,null],[163758,"2026-08-17T13:10:53",17,"/ Окружение используем? Я телепортировался к нему получается он же пытался убегать",162572,null],[163759,"2026-08-17T13:11:21",2,"// он не провоцировал атаку если что, когда бежал, потому что стоял не в 5 футах от вас",163758,null],[163760,"2026-08-17T13:11:55",17,"/Да это понятно я кароче за спину ему прыгнул если окрудение Хб правило не используем бью без преимущества тогда",162572,null],[163761,"2026-08-17T13:11:55",17,"/r +8 Громовой клинок",162572,null],[163763,"2026-08-17T13:11:59",17,"/Бля",162572,null],[163764,"2026-08-17T13:12:02",17,"/ Всё",162572,null],[163765,"2026-08-17T13:12:29",17,"Гром взмахнул клинком но верткий скелет увернулся",162572,null],[163767,"2026-08-17T13:13:23",26,"*беру копье и начинаю рассматривать скелета который будет поближе ко мне*",162572,null],[163769,"2026-08-17T13:13:43",26,"/r 1d20 +5",162572,null],[163771,"2026-08-17T13:14:11",2,"// в смысле рассматривать?",163767,null],[163773,"2026-08-17T13:14:39",26,"Ну в плане то что примерный глазомер подключаю чтобы определить в кто поближе//",162572,null],[163775,"2026-08-17T13:15:02",2,"// ну один из них рядом с тобой, а другой далеко. На что ты куб бросил?",163773,null],[163776,"2026-08-17T13:15:24",26,"На попадание копьем//",162572,null],[163777,"2026-08-17T13:15:44",2,"// бросай на урон",162572,null],[163778,"2026-08-17T13:16:09",26,"/r 1d6 +3",162572,null],[163781,"2026-08-17T13:16:58",2,"Копьё вонзается в грудь скелета. Кости разлетаются по скользкому полу. Он совершает 2 атаки когтями по Азраэлю, который его ранил.",162572,null],[163782,"2026-08-17T13:17:05",2,"/roll d20+4",162572,null],[163786,"2026-08-17T13:17:38",2,"Но обеими атаками промахивается.",162572,null],[163787,"2026-08-17T13:17:52",26,"Конец хода//",162572,null],[163788,"2026-08-17T13:18:24",2,"Следом атакует первый скелет. Он бьёт Орочи когтями и выпивает какую-то флягу.",162572,null],[163789,"2026-08-17T13:18:28",2,"/roll d20+4",162572,null],[163792,"2026-08-17T13:18:48",2,"Но тоже промахивается. Ход Орочи.\n@QURTZZ",162572,null],[163794,"2026-08-17T13:20:18",31,"/roll d20+7, бью ладонью того что меня атаковал",162572,null],[163797,"2026-08-17T13:20:36",31,"/roll d6+4",162572,null],[163814,"2026-08-17T13:34:25",2,"// а почему ты 1 раз бьёшь, если у тебя есть доп атака и вроде бонуской ещё?",163794,null],[163815,"2026-08-17T13:35:05",31,"Сорян, точно, я забыл, давно не играл за него/",163814,null],[163816,"2026-08-17T13:35:11",31,"/roll d20+7",162572,null],[163818,"2026-08-17T13:35:22",31,"/roll d6+4",162572,null],[163820,"2026-08-17T13:35:44",31,"Две мощные оплеухи от Орочи прилетают по голове скелета",162572,null],[163823,"2026-08-17T13:36:48",2,"// ты можешь совершить ещё одну атаку бонусным действием или совершить 2 атаки бонусным действием, но тогда придётся потратить 2 ци",163815,null],[163824,"2026-08-17T13:37:38",2,"// короче суммарно у тебя:\nДействие - 2 атаки\nБонусное действие - если не тратишь ци, то 1 атака. Если используешь шквал ударов (тратит 2 ци) - 2 атаки",162572,null],[163829,"2026-08-17T13:41:13",31,"Ты извини, я могу тормозить с механиками и подсчетами, я все таки новичок))/",162572,null],[163830,"2026-08-17T13:41:41",2,"// можешь 1 или 2 атаки сделать ещё",163829,null],[163831,"2026-08-17T13:48:53",31,"А что, скелет еще жив?/",163830,null],[163832,"2026-08-17T13:49:06",31,"Тогда трачу одно очки и и бье его еще раз",162572,null],[163833,"2026-08-17T13:49:12",31,"/roll d20+7",162572,null],[163835,"2026-08-17T13:49:21",31,"/roll d6+4",162572,null],[163837,"2026-08-17T13:49:28",2,"// ты либо тратишь 2 очка и бьёшь 2 раза, либо не тратишь очки и бьёшь 1 раз",163832,null],[163838,"2026-08-17T13:49:33",2,"// он ещё живой",162572,null],[163839,"2026-08-17T13:49:45",31,"/roll d20+7",162572,null],[163841,"2026-08-17T13:50:04",31,"/roll d6+4 да упокойся ты уже костяшка",162572,null],[163843,"2026-08-17T13:50:49",2,"Скелет получает мощную серию ударов от Орочи и с трудом держится на ногах. Ход Грома\n@dunchev",162572,null],[163844,"2026-08-17T13:51:13",31,"Мне кажется что то не так, должно быть либо два удара (основной и бонусный от боевых искусств), либо три, потому что удары за очки ки считаются бонусными//",162572,null],[163845,"2026-08-17T13:52:36",2,"// У тебя есть умение \"дополнительная атака\". Каждый раз, когда ты совершаешь действие атака, ты делаешь 2 атаки место одной. И у тебя есть бонусное действие. Им ты либо бьёшь 2 раза от шквала ударов, либо бьёшь 1 раз просто так.",163844,null],[163846,"2026-08-17T13:54:32",17,"Гром рассекает скелета мечом из молний",163843,null],[163847,"2026-08-17T13:54:35",17,"/r +8 Ныа",162572,null],[163849,"2026-08-17T13:54:56",17,"/r d10+5 q d8 Огонь",162572,null],[163851,"2026-08-17T13:55:04",26,"Нормальный такой ныа//",162572,null],[163857,"2026-08-17T13:59:00",17,"/ Урон кстате излучением первый у меня",162572,null],[163858,"2026-08-17T14:02:18",26,"Можно кое что спросить?//",162572,null],[163859,"2026-08-17T14:02:30",26,"А по какому из 2 скелетов прошлые две плюхи залетели? //",162572,null],[163860,"2026-08-17T14:02:35",2,"// попал",163850,null],[163861,"2026-08-17T14:02:37",26,"Типо кого орочи и гром бьют? //",162572,null],[163862,"2026-08-17T14:02:50",2,"// Орочи бьёт 1, остальные 2",162572,null],[163863,"2026-08-17T14:03:02",26,"А окей//",162572,null],[163864,"2026-08-17T14:04:46",17,"/ Да нет, я бью того что бьёт орочи",163862,null],[163865,"2026-08-17T14:04:55",17,"/Я к нему телепортировался и долблю с ним одного",162572,null],[163869,"2026-08-17T14:06:17",2,"Первый скелет рассыпается на кости.",162572,null],[163870,"2026-08-17T14:06:26",2,"Кидай урон",163863,null],[163871,"2026-08-17T14:06:34",26,"Что в смысле почему//",163870,null],[163872,"2026-08-17T14:06:57",26,"Так я запутался окончательно//",162572,null],[163873,"2026-08-17T14:06:59",2,".",163854,null],[163874,"2026-08-17T14:07:15",26,"Так это гром еще//",162572,null],[163875,"2026-08-17T14:07:30",26,"Так передо мной скелет1//",162572,null],[163876,"2026-08-17T14:07:32",26,"Так ?//",162572,null],[163878,"2026-08-17T14:07:40",26,"А не скелет 2//",162572,null],[163879,"2026-08-17T14:08:08",17,"/ Это кто то нажал, у меня 1 атака",163873,null],[163880,"2026-08-17T14:08:08",2,"Тяжело без карты играть",162572,null],[163881,"2026-08-17T14:08:21",2,"Давайте я овлбир для боёв в дальнейшем подрубать буду",162572,null],[163882,"2026-08-17T14:08:26",17,"/Да не парься",162572,null],[163883,"2026-08-17T14:08:34",17,"/ В двух скелетах запутались",162572,null],[163884,"2026-08-17T14:08:50",26,"Так в итоге эти двое добили 1 скелета , а 2 скелет передо мной?//",162572,null],[163886,"2026-08-17T14:09:32",17,"/ Тебе нужно понять\n\n1 сдох, другой не сдох\n\nКоторый живой перед тобой",162572,null],[163894,"2026-08-17T14:10:07",26,"Че происходит?//",162572,null],[163896,"2026-08-17T14:10:12",17,"Ты упал",162572,null],[163897,"2026-08-17T14:10:21",26,"Так я еще не ходил//",162572,null],[163898,"2026-08-17T14:10:58",2,"// Бля как тяжело бои вести без карты и нормального трекера инициативы, куча лишнего текста и кубов",162572,null],[163899,"2026-08-17T14:11:28",2,"// ходи, этого не было значит",162572,null],[163901,"2026-08-17T14:11:51",26,"Короче щас скелет передо мной , основное действие я трачу на уклонение , а допом через 1 ячейку оруженосца бью левым мечом по скелету //",162572,null],[163902,"2026-08-17T14:12:10",26,"/r 1d20 +5",162572,null],[163905,"2026-08-17T14:12:30",2,"// а как ты бонуской бьёшь",162572,null],[163906,"2026-08-17T14:12:31",26,"//бью с преимуществом как раз из-за той самой ячейки",162572,null],[163907,"2026-08-17T14:12:35",17,"/ Один раз за ход, когда вы совершаете по существу атаку оружием, вы можете совершить её с преимуществом.",162572,null],[163908,"2026-08-17T14:12:40",26,"Оруженосец//",162572,null],[163909,"2026-08-17T14:12:40",17,"/ Ты не можешь нужно атаковать",162572,null],[163910,"2026-08-17T14:12:50",2,"// что это",163908,null],[163911,"2026-08-17T14:13:17",2,"// хб черта, понял",162572,null],[163912,"2026-08-17T14:13:41",26,"Не хб я нашел проеб//",162572,null],[163913,"2026-08-17T14:13:42",2,"// но я не вижу, где здесь даётся атака бонуской",162572,null],[163914,"2026-08-17T14:13:56",26,"Короче просто уклонение и конец хода //",162572,null],[163915,"2026-08-17T14:14:10",17,"/ https://dnd.su/feats/252-squire-of-solamnia/",162572,null],[163916,"2026-08-17T14:14:16",2,"Скелет бьёт паладина дважды и бежит.",162572,null],[163917,"2026-08-17T14:14:22",2,"/roll d20+4",162572,null],[163920,"2026-08-17T14:14:39",2,"/roll d8+2 d8+2",162572,null],[163922,"2026-08-17T14:14:53",2,"5 урона от первой",162572,null],[163925,"2026-08-17T14:15:32",2,"Азраэль без сознания.",162594,null],[163927,"2026-08-17T14:16:11",2,"Ход Орочи. Скелет в 100 футах от тебя, ты видишь лишь его силуэт.",162572,null],[163928,"2026-08-17T14:16:16",2,"@QURTZZ",162572,null],[163950,"2026-08-17T14:36:07",26,"*упал как старый шкаф прямиком на спину раскинув руки и ноги в сторону (звездой упал)*",162572,null],[163959,"2026-08-17T14:48:41",31,"Он убегает?/",163927,null],[163960,"2026-08-17T14:49:04",17,"/Около тебя упал уже скелет, этот подальше от тебя",162572,null],[163961,"2026-08-17T14:49:07",17,"/ Ебаш его",162572,null],[163968,"2026-08-17T14:49:48",31,"Упал и сдох или просто лежит чиллит?/",163960,null],[163969,"2026-08-17T14:50:06",17,"/Сдох",162572,null],[163971,"2026-08-17T14:50:16",17,"/ Мы его загасили, а другой нашего первака положил",162572,null],[163973,"2026-08-17T14:51:36",31,"100 футов я не догоню даже рывком, у меня скорость без оружия в руках 45, рывком будет 90//",162572,null],[163974,"2026-08-17T14:51:59",17,"/ Так он не так далеко вроде",162572,null],[163976,"2026-08-17T14:52:09",31,"Написано 100 футов/",162572,null],[163977,"2026-08-17T14:52:17",17,"/ Ну ладно",162572,null],[163980,"2026-08-17T14:55:21",31,"Так, я его дротиком уебу, трачу движение чтобы приблизится на 40 футов, достаю болтик и швыряю в него",162572,null],[163981,"2026-08-17T14:55:28",31,"/roll d20+6",162572,null],[163985,"2026-08-17T14:55:47",31,"/roll d4+3",162572,null],[163989,"2026-08-17T14:57:05",17,"А гром огненный снаряд ему в спину метает и бежит к раненому паладину",162572,null],[163990,"2026-08-17T14:57:13",17,"/r +7 Снаряд",162572,null],[163992,"2026-08-17T14:57:20",17,"/r 2d10 Если попал",162572,null],[163997,"2026-08-17T15:08:43",26,"Удаляюсь на минут 20//",162572,null],[164014,"2026-08-17T15:28:00",26,"Я тут//",163997,null],[164015,"2026-08-17T15:31:29",2,"// ты попал, но можешь объяснить, почему 2д10?",163992,null],[164021,"2026-08-17T15:44:39",17,"когда вы достигаете 5-го уровня (2к10",162572,null],[164022,"2026-08-17T15:44:45",17,"Огненный снаряд",162572,null],[164023,"2026-08-17T15:49:57",2,"// забыл, что ты 5 уровень",162572,null],[164024,"2026-08-17T15:50:12",26,"Спас от смерти?//",162572,null],[164025,"2026-08-17T15:50:22",31,"Завалили мы скелета?/",162572,null],[164026,"2026-08-17T15:51:12",2,"Последний скелет тоже рассыпается на кости. Битва не была тяжёлой, но таких стычек будет огромное количество. А много боёв измотает даже опытный отряд. Бой окончен. А загадка с окнами по-прежнему не решена.",162572,null],[164027,"2026-08-17T15:52:02",31,"Подхожу к павшкму товарищу чтобы оказать помощь",162572,null],[164028,"2026-08-17T15:52:13",31,"/roll d20+4 медицина",162572,null],[164030,"2026-08-17T15:52:28",31,"Описать?/",162572,null],[164031,"2026-08-17T15:52:45",2,"// Если хочешь, он очнётся через",162572,null],[164032,"2026-08-17T15:52:49",2,"/roll d4",162572,null],[164034,"2026-08-17T15:52:56",2,"// 4 часа или пока не получит хилл",162572,null],[164035,"2026-08-17T15:53:51",31,"Осматриваю тело Палладина, используя свои знания монаха о точках в человеческом теле, нажимаю на те из них, что блокируют отток жизненной силы. \n\n- теперь не умрет",162572,null],[164036,"2026-08-17T15:54:23",31,"Достаю один из сосудов с зельем здоровья и вливаю в него",162572,null],[164037,"2026-08-17T15:54:36",31,"Что бросать?/",162572,null],[164038,"2026-08-17T15:55:12",31,"/roll 2d4+2 на хиты от зелья",162572,null],[164040,"2026-08-17T15:55:12",26,"2к4+2 вроде//",162572,null],[164041,"2026-08-17T15:55:15",2,"// на хилл, 2д4+2?",164037,null],[164042,"2026-08-17T15:55:52",26,"*открываю глаза наполненные новой энергией и начинаю приподниматься* \n— Кхэ не подрасчитал силенок",162572,null],[164043,"2026-08-17T15:56:20",2,"Азраэль встаёт с 7 ХП. Вы понимаете, что здесь очень холодно. Даже тёплые шубы не спасают от мороза и по-хорошему стоит сделать привал у костра.",162572,null],[164044,"2026-08-17T15:56:36",31,"Тебе лучше держаться за мной и Громом, если тебя может так сильно поранить даже скелет, то тебе будет очень тяжело тут",164042,null],[164045,"2026-08-17T15:56:50",26,"— ну и холодрыга поди всю спину отморозил пока валялся , а вы как?",162572,null],[164046,"2026-08-17T15:56:58",26,"*кивнул*",164044,null],[164047,"2026-08-17T15:57:21",31,"- я нашёл еще одну руну, но добраться до нее н юе смогу скорее всего",162572,null],[164048,"2026-08-17T15:57:37",26,"— хммм давайте вместе попробуем ее сюда перетащить",162572,null],[164049,"2026-08-17T15:57:56",26,"—А после будем думать и обсуждать последовательность согреваясь у костра",162572,null],[164050,"2026-08-17T15:58:18",31,"- Я слишком тяжелый, не пройду там по льду",162572,null],[164051,"2026-08-17T15:58:34",26,"— Если вы не против я пока попробую разжечь костерчик *достал трутницу , а по пути к пьедесталам забрал копье из скелета *",162572,null],[164052,"2026-08-17T15:59:06",26,"— Гм, делема , но думаю если мы с громом снимем броню то в теории сможем перебраться туда",164050,null],[164053,"2026-08-17T15:59:55",26,"— У тебя есть трутница?  если нет то могу дать чтобы ты разжег костер",162572,null],[164054,"2026-08-17T15:59:55",31,"- Вы обморозитесь",164052,null],[164055,"2026-08-17T16:00:05",31,"- есть",162572,null],[164056,"2026-08-17T16:00:06",26,"— Ну так шубу оставим",162572,null],[164057,"2026-08-17T16:00:52",31,"- хорошо. Я займусь костром, а вы попробуйте достать ту руну. Один пусть идет, а второй держит его на веревке, чтобы вытащить если что",162572,null],[164058,"2026-08-17T16:01:24",26,"—Отлично ,Гром , как тебе идея?",162572,null],[164059,"2026-08-17T16:02:19",31,"- стоп, а как же наш товарищ волшебник? Он не может своей невидимой рукой достать?",162572,null],[164061,"2026-08-17T16:03:53",26,"— так стоп точно! Волшебник *повернул голову в сторону где приблизительно был*\n— черт он наверное уже обмерз, надо бы его поднять \n*подошел к Волшебники и отодвинул камень с мантии взял фокусировку вложил в руку и понес до наги*",162572,null],[164062,"2026-08-17T16:06:38",2,"@Pro551o",162572,null],[164072,"2026-08-17T16:20:20",26,"@dunchev",162572,null],[164073,"2026-08-17T16:21:19",17,"— Постамент с руной воды нужен, такс какие варианты?",162572,null],[164077,"2026-08-17T16:22:04",17,"Гром подходит к тонкому льду и начинает под собой создавать ледяную корку более плотную чем была\n\n/Заговор формирование воды\n\nПостепенно дварф идёт к постаменту, берет его и возвращается так же с помозью магии",162572,null],[164078,"2026-08-17T16:23:28",26,"*стоял с веревкой в руках и смотрел за Громом* \n\n— чтож ладно \n\n*вернулся к Орочи(мару)*",162572,null],[164079,"2026-08-17T16:23:32",26,"Ладно давайте снова",162572,null],[164083,"2026-08-17T16:25:25",26,"— Получается свет у нас последний, холод должен быть после воды , но после воды идет луна , а огонь идет после холода хммм",162572,null],[164084,"2026-08-17T16:25:26",17,"— Идея с веревками тоже ничего, в другой раз обязательно",162572,null],[164085,"2026-08-17T16:25:40",17,"— Луна до воды",164083,null],[164086,"2026-08-17T16:26:14",26,"— Аааа следует за , точно",162572,null],[164087,"2026-08-17T16:26:17",26,"Получаеттся",162572,null],[164088,"2026-08-17T16:26:27",17,"Дварф пошел ставить руны ☽ 💧 ❄️  🔥  ❖",162572,null],[164089,"2026-08-17T16:26:31",26,"—Луна, вода ,холод ,огонь ,свет",162572,null],[164090,"2026-08-17T16:26:39",17,"— Да, вот так",162572,null],[164091,"2026-08-17T16:27:23",26,"— Вот так то лучше",162572,null],[164095,"2026-08-17T16:32:26",2,"Дварф поставил руны в нужном порядке. Сработал механизм, один из пьедесталов опустился вниз, открывая углубление в полу. В нём лежал тяжёлый металлический ключ. Неизвестно, что именно он открывал, но, возможно, он пригодится в будущем?",162572,null],[164097,"2026-08-17T16:34:35",26,"— Ключик ключик ключик откуда же ты ключик",162572,null],[164098,"2026-08-17T16:34:49",2,"@QURTZZ @dunchev",162572,null],[164099,"2026-08-17T16:35:55",31,"/roll d20+4 на внимательность, осматриваю ключ, не опасно ли его брать?",162572,null],[164101,"2026-08-17T16:36:35",2,"Это обычный ключ.",164099,null],[164102,"2026-08-17T16:37:01",31,"Беру ключ, пригодится",162572,null],[164103,"2026-08-17T16:37:26",31,"Осматриваемся, все ли в этйо комнате мы увидели?",162572,null],[164107,"2026-08-17T16:39:13",26,"— Да-с хоромы огромные, интересно а кто вырубал все , мы же в промёрзший горной пороже сидим если так подумать *сидел и размышлял*",162572,null],[164123,"2026-08-17T16:47:32",26,"— Хммм посидим у костра и потом двинем дальше в путь?",162572,null],[164128,"2026-08-17T16:48:38",2,"В дальнем углу за грудой обломков ты замечаешь следы, ведущие в следующий коридор. Следы ведут в темноту. Они похожи на человеческие, но немного меньше, чем у взрослого человека.",164103,null],[164136,"2026-08-17T16:51:45",17,"— Может это следы сына кузнеца. Вроде он пропал. Что ж.Я пойду первым! Прикрою вас!\n\nЧародей пошагал вперед по следам",162572,null],[164138,"2026-08-17T16:53:03",26,"—Эй эй! А согреться! \n\n*быстро подскочил и направился за громом*",162572,null],[164157,"2026-08-17T16:59:55",17,"Около Электрического меча было тепло и светло",164138,null],[164253,"2026-08-17T17:38:04",23,"чего//",164062,null],[164255,"2026-08-17T17:38:25",23,"Я вроде говорил то что я занятой чебурек//",162572,null],[164271,"2026-08-17T17:48:01",2,"// бой закончился",164253,null],[164306,"2026-08-17T17:54:17",23,"мня не был.... Зачем меня теготь//",162572,null],[164311,"2026-08-17T17:57:24",26,"//все чуток и сплю",162572,null],[164369,"2026-08-17T19:48:38",2,"Следы вели не через главный проход, а скрытый. Они привели вас в большой, грубо вырубленный зал. Здесь явно живут. В центре горит небольшой костёр, дым уходит в трещину на потолке. Вокруг костра разбросаны шкуры, тряпки и обглоданные кости. У стен стоят грубо сколоченные ящики и бочки, некоторые из них явно с припасами.\n\nВ комнате находится очень много гоблинов. У костра сидят две самки, они что-то варят в ржавом котле. Рядом с ними двое маленьких гоблинят играют с костью, делая вид, что это оружие. Один из них поднимает голову и смотрит на вас широко раскрытыми глазами. Трое гоблинов-воинов сидят в углу и точат свои ножи. Остальные либо спят, либо занимаются своими делами. На первый взгляд их тут около 25, может больше. При вашем появлении они замирают, но нападать никто не спешит. Костёр трещит, дым поднимается к потолку. Пахнет жареным картофелем.",162572,null],[164370,"2026-08-17T19:48:57",2,"@Pro551o @QURTZZ @dunchev @Shadiq_an",162572,null],[164374,"2026-08-17T20:03:00",17,"— Хер с ними парни. Валим назад. Улыбаемся и машем. Улыбаемся. И машем.\n\n— Это не наша цель, насрать нам на зеленозадых",162572,null],[164375,"2026-08-17T20:03:24",17,"Гром пятится назад к выходу улыбается во все зубы и машет",162572,null],[164383,"2026-08-17T20:27:42",2,"Гоблины смотрят на Грома, но не принимают никаких действий. Мужчины даже не достали оружия.",164375,null],[164391,"2026-08-17T20:30:08",23,"бля именно тогда когда я ебусь с ноутом.....///",164370,null],[164392,"2026-08-17T20:31:03",23,"ладно как меня вообще собираются добавлять//",162572,null],[164396,"2026-08-17T20:46:30",17,"/ Да мы только одну загадку решили и щас комната гоблинами.\n\nТы волшебник гари\n\nПросто пуф и появился",162572,null],[164397,"2026-08-17T20:46:34",17,"/ Но игроков нету",162572,null],[164401,"2026-08-17T20:49:50",2,"// я всё равно спать уйду скоро",164391,null],[165181,"2026-08-19T10:54:42",2,"@dunchev @QURTZZ @Shadiq_an @Pro551o",162572,null],[165183,"2026-08-19T10:57:11",17,"/Я тут",162572,null],[165186,"2026-08-19T11:51:46",31,"Тоже тут/",162572,null],[165187,"2026-08-19T11:54:37",17,"/ Пиши реакт на поселение гоблинов, я думаю надо просто съебать",162572,null],[165188,"2026-08-19T11:54:47",17,"/ Не наш уровень слишком слабые",162572,null],[165189,"2026-08-19T12:01:07",31,"- стая гоблинов, и странно не агрессивные. Может, они не опасны? Сами пытаются выжить в холоде?",162572,null],[165190,"2026-08-19T12:06:38",26,"Тут//",162572,null],[165191,"2026-08-19T12:07:17",26,"— скорее всего так и есть, может пройти мимо аккуратно?",162572,null],[165192,"2026-08-19T12:07:59",17,"Гром пятясь назад кивает и выходит из комнаты\n\n— Нам надо за сбежавшим скелетом",162572,null],[165193,"2026-08-19T12:16:10",31,"- так мы обоих уложили",165192,null],[165194,"2026-08-19T12:16:40",31,"- Ну давайте осмотрим комнату еще раз, пчть ли там еще какой проход, кроме комнаты с гоблинами",162572,null],[165195,"2026-08-19T12:18:05",31,"/roll d20+4 на восприятие, осматриваем комнату и ищем иные выходы",162572,null],[165197,"2026-08-19T12:18:27",17,"— Ну он же куда то пытался в другой проход сдриснуть",162572,null],[165198,"2026-08-19T12:18:31",17,"— ВОт туда пошли",162572,null],[165221,"2026-08-19T13:30:21",26,"Буду некоторое время отсутствовать //",162572,null],[165235,"2026-08-19T13:35:48",2,"// скелет бежал в другой конец комнаты, и его добили. Вы сейчас находитесь в огромном зале гоблинов, дальше пути нет. Нужно возвращаться и идти в другое место",165198,null],[165264,"2026-08-19T14:23:49",26,"*быстрыми шажками вышел обратно то помещение где мы и были изначально* \n\n— похоже нам следует пойти обратно на развилку и все же сходить на лево",162572,null],[165265,"2026-08-19T14:25:04",17,"— Пошлите сюда, чего застыли!?\n\nГром шагает в проход в который пытался убежать скелетрон, \n\n— Вот думаю правильно, что гоблинов оставили в покое пусть живут детишек нянчат, будут плохо себя вести, мы придём конкретно за ними",162572,null],[165266,"2026-08-19T14:25:16",17,"/Мастер идём в проход другой доступный от гоблинов уходим",162572,null],[165272,"2026-08-19T14:30:41",26,"*шел ровно за громом*\n\n— да идем мы идём",162572,null],[165289,"2026-08-19T14:57:21",31,"Скольжу следом",162572,null],[165290,"2026-08-19T15:19:21",2,"Скелет бежал не в сторону прохода, а к стене, но значения это не имеет. Группа вернулась в предыдущий зал и отправилась дальше. Становилось всё холоднее и холоднее. Настолько, что даже тёплая одежда полностью не спасала от мороза. А у Волшебника её вроде как не было, поэтому ему ещё хуже (если есть тёплая одежда, то он чувствует себя также, как остальные). Весь отряд находится под первой стадией эффекта мороза до того, как согреется (короткий или длинный отдых у костра снимает 1 уровень мороза), Волшебник получает сразу 2 стадии.\n1. Дрожь. Даёт штраф пять футов к скорости.\n2. Скованность. Даёт помеху на проверки Восприятия и Ловкости.\n\n\nДалее необходимо было выбрать одну из двух дверей. На одной был знак \"🔥\", а на другой — \"❄️\". Кажется, на полу был какой-то текст, но его замело снегом.",165265,null],[165291,"2026-08-19T15:19:30",2,"@dunchev @Shadiq_an @QURTZZ @Pro551o",162572,null],[165292,"2026-08-19T15:21:05",31,"- парни, я чертовски замерз. Пойдемте в комнату с огоньком",162572,null],[165293,"2026-08-19T15:23:13",26,"— погоди, тут что-то было \n\n*стал руками разгребать снег пытаясь докопаться до пола*",162572,null],[165294,"2026-08-19T15:27:02",2,"Ты разгребаешь снег и видишь, что на каменном полу начертан текст: \"Тот, кто боится холода, уже мёртв. Тот, кто принимает его, никогда не умрёт.\"",165293,null],[165295,"2026-08-19T15:28:14",31,"- хмм, похоже, нужна все таки дверь с со снежинкой",165294,null],[165297,"2026-08-19T15:29:36",26,"— видимо так , но костер в любом случае необходим",162572,null],[165337,"2026-08-19T16:29:15",23,"заеба...///",162572,null],[165338,"2026-08-19T16:29:28",23,"когда же у меня график наладится//",162572,null],[165339,"2026-08-19T16:33:43",26,"Однажды//",165338,null],[165358,"2026-08-19T17:18:52",26,"//как у вас завтра по занятости? До 14:00 могу спокойно отписывать посты , ну а там уже к 16:00 вернусь",162572,null],[165360,"2026-08-19T17:19:55",31,"Я свободен с 8 до 13 по мск, потом где то с 16 до 20",162572,null],[165387,"2026-08-19T18:12:38",2,"// я свободен практически 24/7",165358,null],[165875,"2026-08-20T11:32:33",2,"@dunchev @Shadiq_an @QURTZZ @Pro551o",162572,null],[165877,"2026-08-20T11:34:04",31,"Тут/",162572,null],[165880,"2026-08-20T11:35:17",26,"Тут//",162572,null],[165881,"2026-08-20T11:35:24",26,"Но через минут 20 я пропаду//",162572,null],[166002,"2026-08-20T13:36:03",17,"/ Мы готовы узреть новую ловушку/комнату с врагами/ загадку/ социальную сцену всё что угодно",162572,null],[166005,"2026-08-20T13:36:37",2,"// ну так какую дверь вы выбираете",166002,null],[166006,"2026-08-20T13:36:54",17,"/ Любую",162572,null],[166007,"2026-08-20T13:36:57",17,"/ Нам пофиг",162572,null],[166008,"2026-08-20T13:37:01",17,"/ Веди нас по рельсам плиз",162572,null],[166009,"2026-08-20T13:37:08",17,"/ В ТРП никто не может играть в кишку",162572,null],[166010,"2026-08-20T13:37:14",17,"/ Никто не понимает какие есть проходы",162572,null],[166011,"2026-08-20T13:37:23",2,".",165290,null],[166012,"2026-08-20T13:37:28",2,".",165294,null],[166013,"2026-08-20T13:37:35",17,"В сторону льда выбрали выше",162572,null],[166014,"2026-08-20T13:37:46",17,"Дварф с ноги выбивает дверь в комнату со снежинкой",162572,null],[166015,"2026-08-20T13:37:50",17,"/r -1 НЫА",162572,null],[166022,"2026-08-20T13:41:14",2,"Дварф со всей силы бьёт ногой по каменной двери. Дверь не шелохнулась, только глухой гул разнёсся по коридору. Дварф отдёргивает ногу, шипя от боли. Нужно было просто дёрнуть за ручку. Группа прошла внутрь. Идти было невероятно холодно, и вы уже хотели было повернуть назад, как вдруг увидели впереди костёр. Он потух, но рядом лежало огромное количество веток, и его можно было развести заново.",166014,null],[166076,"2026-08-20T14:10:55",17,"/Как на нас реально работает холод механически?",162572,null],[166077,"2026-08-20T14:10:59",17,"/ Истощения/дебаффы",162572,null],[166078,"2026-08-20T14:11:07",17,"/ Пока этого нет типо похуй идём дальше",162572,null],[166079,"2026-08-20T14:11:33",17,"/ Я могу создавать огонь, дилема замёрзнуть если ты маг, мягко говоря натянута",162572,null],[166080,"2026-08-20T14:11:43",26,"У нас истощение с дебаффом уже//",166079,null],[166082,"2026-08-20T14:11:57",26,".",165290,null],[166083,"2026-08-20T14:11:58",17,"/ Где поиск не находит",162572,null],[166084,"2026-08-20T14:12:09",17,"/Ага",162572,null],[166086,"2026-08-20T14:12:38",17,"— Думаю мы можем потерпеть и не останавливаться тут, пойдемте дальше друзья!",162572,null],[166087,"2026-08-20T14:12:55",17,"Дварф взял волшебную кружку где появилось пойло и выпил залпом горячительного напитка",162572,null],[166094,"2026-08-20T14:17:25",26,"//я все пропадаю на пару часов",162572,null],[166097,"2026-08-20T14:17:47",31,"- плесни и мне пожалуй, а то я уже хвоста не чувствую",166087,null],[166109,"2026-08-20T14:45:14",17,"Дварф развернулся и снова в кружке наколдовалось пойло\n\n— Держи змий, свежее",166097,null],[166113,"2026-08-20T14:49:56",31,"- буль-буль-буль",162572,null],[166114,"2026-08-20T14:50:16",17,"/ Пишите согласны пройти мимо костра? Или хотите остаться",162572,null],[166115,"2026-08-20T14:50:23",17,"/ Мастер ждёт решения, а я не могу за всех решать",162572,null],[166116,"2026-08-20T14:50:26",17,"/ Но уже на грани",162572,null],[166118,"2026-08-20T14:57:32",31,"- Давайте погреемся, пока етсь шанс",162572,null],[166120,"2026-08-20T15:04:22",17,"— Да тут жопу отморозим, даже с костром, может быть холод прекратится скоро? Тем более на двери было написано \"Кто холода боится сдохнет, кто не ссыт тот станет бессмертным\" чето вроде такое",162572,null],[166126,"2026-08-20T15:29:23",31,"- знаешь, я придерживаюсь мнения что не замерзает только тот, кто не забывает греться",166120,null],[166129,"2026-08-20T15:29:56",17,"— Тыж хлоднокровная гадюка! Зачем тебе греться\\",162572,null],[166140,"2026-08-20T15:44:05",31,"- во первых, сам ты гадюка. Во вторых, моя природа действительно хладнокровная, но жить без тепла я не могу, мы, наги, как и наши дальние родичи, обычные змеи, не можем долго существовать без тепла, становимся вялыми и сонными. Наша хладнокровность это не панацея от холода, это скорее наоборот, проклятие для жизни там, где нет солнца и тепла",166129,null],[166244,"2026-08-20T17:58:28",26,"*наконец выйдя из транса влился в суть разговора*\n\n— вообще бессмертие можно подразумевать по разному , по сути своей если твое тело не будет разлагаться то оно будет вечным и бессмертным...\n\n*момент просветления окончен интеллект снова на 8*\n\n— так а чем это я, а да жрать охота и холодно",162572,null],[166350,"2026-08-20T18:20:22",17,"— Ну ладно неженки! \n\nДварф пробурчал себе под нос, собрал палки в охабку и поджег заговором\n\n— Грейтесь!\n\nГром достал свой спальник и залез в него как гусеничка",162572,null],[166360,"2026-08-20T18:22:58",31,"Орочисвероулся клубком и протянул к огню озябшие руки. Живой огонь в этом месте казался чем то нереальным, словно кусочек солнца, он завораживал и словно просил: не уходите, там смерть, останьтесь тут",162572,null],[166384,"2026-08-20T18:27:50",2,"// Вы все ложитесь спать?",162572,null],[166386,"2026-08-20T18:28:10",17,"/ Давайте хотябы короткий",162572,null],[166387,"2026-08-20T18:28:10",31,"Думаю короткого достаточно/",162572,null],[166388,"2026-08-20T18:28:13",17,"/ На часик",162572,null],[166389,"2026-08-20T18:28:18",31,"Чисто чиллим у костра/",162572,null],[166393,"2026-08-20T18:28:53",2,"Вы греетесь у костра, и вам сразу становится теплее. Похоже, можно продолжать путь дальше.",162572,null],[166398,"2026-08-20T18:29:40",31,"- кажется, костре затухает. Унесём его жар в себе, пора идти дальше. Комната со снежинкой нас ждёт",162572,null],[166404,"2026-08-20T18:31:03",2,"// давайте я отпишу, что вы пошли дальше",162572,null],[166405,"2026-08-20T18:31:10",31,"Ок/",162572,null],[166408,"2026-08-20T18:33:25",31,"Азраэлю на хп бы кости бросить не помешало на коротком/",162572,null],[166410,"2026-08-20T18:34:22",2,"Группа идёт дальше. Вы входите в комнату, где в центре на коленях застыло тело стражника в плаще с гербом герцога, который вас нанял. Из спины торчит обломок ледяного копья. Кровь под ним застыла чёрной лужей, уходящая дорожкой вглубь коридора.\nНа поясе у него сумка. Внутри приказ: герцог приказывает разобраться с аномалией в лаборатории. Нужно докладывать каждый день.\nВ руках у него дневник. Последняя запись: \"Надеюсь, это кто-то найдёт. Оно уже близко. Это место совсем не такое как везде: монстры без зрачков, галлюцинации, жуткий холод. Копьё вошло в спину, когда я бежал. Я чувствую, как замерзаю изнутри. Если вы это читаете, не идите за кровавым следом. Это ловушка.\"",162572,null],[166419,"2026-08-20T18:38:22",31,"/roll d20+4 на внимательность или проницательность. Осматриваю копье и пытаюсь понять его природу, что это, оружие или может часть тела монстра?",162572,null],[166475,"2026-08-20T19:05:50",2,"Ты подходишь ближе и осматриваешь копьё. Оно не металлическое и не деревянное, а ледяное, с прожилками тёмного, как застывшая кровь, цвета внутри. На конце неровный скол, будто копьё не было выковано, а выросло. Природа явно не естественная. Вряд-ли это оружие, скорее часть тела или порождение существа, которое может создавать лёд. На ощупь оно холоднее, чем окружающий воздух, и кажется, что оно всё ещё излучает холод, даже после того как пронзило стражника. Ты видишь, что из коридора ведёт багровый след. Если выйти в коридор, то можно заметить, что стены забрызганы кровью. Но было тихо, слишком тихо для подземелья. В конце коридора ты замечаешь свечение. Из темноты тебя словно сверлят 2 ярких небольших \"прожектора\", скорее всего это глаза.",166419,null],[166476,"2026-08-20T19:06:39",26,"Ща ща//",166408,null],[166477,"2026-08-20T19:08:17",31,"- кажется, в этот коридор лучше не соваться",162572,null],[166478,"2026-08-20T19:09:32",26,"Можно же восстановить хиты?//",162572,null],[166479,"2026-08-20T19:09:50",26,"/r 1d10+2",162572,null],[166481,"2026-08-20T19:11:36",26,"—Сама рациональность и благоразумность",166477,null],[166482,"2026-08-20T19:12:02",26,"//все я спать",162572,null],[166483,"2026-08-20T19:12:43",31,"Я тоже скоро ложусь/",162572,null],[167016,"2026-08-21T12:22:47",26,"Доброе утро всем//",162572,null],[167025,"2026-08-21T12:26:06",31,"Не утро уже/",162572,null],[167029,"2026-08-21T12:29:15",17,"/ ТАК ЧЕГО?! УСКОРЯЕМСЯ!",162572,null],[167030,"2026-08-21T12:30:43",17,"— Не идите за кровавым следом. Ловушка. Таааак. Значит он бежал от кого то и кровавый след нам выведет к гаду, кто его копьём пронзил. Может быть там эта лаборатория",166410,null],[167031,"2026-08-21T12:30:49",26,"//ДЫААА!",167029,null],[167034,"2026-08-21T12:31:37",26,"— ну вообще так наверное и есть, но не глупо ли будет идти прямо в лоб тому что мы вообще не знаем?",162572,null],[167035,"2026-08-21T12:31:39",17,"— Так а куда мы можем пойти если не по кровавой дорожке то?\n\nДварф осматривается какие есть проходы",162572,null],[167036,"2026-08-21T12:32:08",17,"— Ну вообще предупрежден значит вооружен, а добрый драки я не боюсь, но если тварь галлюцинации насылает, ууу сука, тут уже сложнее",162572,null],[167037,"2026-08-21T12:32:33",26,"— Может продвинимся , а там я попробую снова что-нибудь засечь?",162572,null],[167040,"2026-08-21T12:33:30",17,"— Ну погнали, хааааах. Пока не вогнали",162572,null],[167041,"2026-08-21T12:33:58",17,"Дварф топает по дорожке из крови первым",162572,null],[167043,"2026-08-21T12:34:39",26,"*отряхнувшись встал и начал расталкивать остальных* \n\n— давай-те встаем поднимаемся , а то Гром и без нас убежит",162572,null],[167047,"2026-08-21T12:41:07",31,"- Не убежит\n\nВыдвинулась, Гром ведёт",162572,null],[167048,"2026-08-21T12:41:29",26,"*пошел следом прихватив Волшебника*",162572,null],[167051,"2026-08-21T12:42:05",31,"Волшебник по моему уже на другой квест записался/",162572,null],[167054,"2026-08-21T12:44:18",26,"А да//",162572,null],[167057,"2026-08-21T12:44:35",26,"Ну ладно //",162572,null],[167081,"2026-08-21T12:52:32",17,"/ Как пришел так и ушел",162572,null],[167088,"2026-08-21T12:56:00",26,"Увидел рожи и обратно выкопался//",162572,null],[167259,"2026-08-21T14:19:36",26,"— можно ли позавдать вопросы пока мы идем?",162572,null],[167263,"2026-08-21T14:20:36",17,"— Спрашивай, ведь мы всего лишь идём по кровавой тропе по которой нас предупредили не ходить",162572,null],[167284,"2026-08-21T14:32:33",2,"Волшебник наступил на ловушку и провалился в глубокую яму. Вы пытались докричаться до него, но он не отвечал — тот пропал неизвестно куда. \n\nВы приближаетесь к источнику свечения. В конце коридора стоит существо. Оно похоже на обмороженный труп, который сохранил форму человека, но перестал быть им. Его кожа серая, с синеватым отливом, кое-где лопнула, из трещин сочится слабый голубоватый свет. Глаза горят, словно прожектора. На нём порванный плащ, а место рук — \"копья\", похожие на то, которое было воткнуто в стражника. Существо не двигается, но смотрит на вас как хищник на добычу. Из его рта вырывается лёгкий пар. Вокруг него холодно, даже если отойти на несколько шагов.",162572,null],[167287,"2026-08-21T14:32:55",2,"// Бросайте инициативу",162572,null],[167289,"2026-08-21T14:33:08",2,"// как вам идея провести бой на овлбире?",162572,null],[167292,"2026-08-21T14:33:36",26,"Ого это будет 1 раз//",162572,null],[167296,"2026-08-21T14:34:01",26,"/roll@roll_bot",162572,null],[167298,"2026-08-21T14:34:08",26,"Ну как всегда //",162572,null],[167304,"2026-08-21T14:37:07",26,"Давай почему бы и нет//",167289,null],[167305,"2026-08-21T14:37:14",26,"Может начнем окружение использовать я хз//",162572,null],[167311,"2026-08-21T14:41:13",26,"*наклонился ближе к двум и прошептал еле слышно* \n\n— Гром, Орочи, нужно жечь его",162572,null],[167322,"2026-08-21T14:48:21",31,"Что это такое?/",167289,null],[167323,"2026-08-21T14:49:01",31,"/roll d20+3 инициатива Орочи",162572,null],[167339,"2026-08-21T14:55:03",2,"owblear.rodeo",167322,null],[167340,"2026-08-21T14:55:24",26,"Типо онлайн стола//",167322,null],[167353,"2026-08-21T14:57:09",26,"Owlbear вроде//",162572,null],[167354,"2026-08-21T14:57:27",26,"owlbear.rodeo",162572,null],[167355,"2026-08-21T14:57:36",26,"Очепятка//",167339,null],[167359,"2026-08-21T14:57:59",31,"Так, я где то через час пропаду, буду за рулем порядка 3-4 часов. Завтра скорее всего тоже буду почти весь день за рулем//",162572,null],[167363,"2026-08-21T14:59:00",17,"— БЛЯЯЯЯТЬ",162572,null],[167365,"2026-08-21T14:59:29",17,"/r +3 Инициатива",162572,null],[167375,"2026-08-21T15:03:07",26,"*тупо смотрел сквозь прорезь шлема то на товарищей то на вот это вот и добавил*\n\n— а мне и я всегда говорили что вот эта магия мракобесная до добра не доводит",162572,null],[167505,"2026-08-21T17:09:32",2,"/roll d20",162572,null],[167508,"2026-08-21T17:10:12",2,"https://www.owlbear.rodeo/room/0i3cdKsFkTB5/The%20Stony%20Wings",162572,null],[172426,"2026-08-25T13:55:33",26,"Ребят//",162572,null],[172427,"2026-08-25T13:55:49",26,"Помоему игра замерзла также как и сердце того архимага)))///",162572,null],[172429,"2026-08-25T13:56:00",26,"Может отпишимся кто когда может играть //",162572,null],[172430,"2026-08-25T13:56:08",26,"И если что то добьём уже//",162572,null],[172431,"2026-08-25T13:56:28",26,"Предлагаю также может на гоблиску боблинскую ярмарку?//",162572,null],[172438,"2026-08-25T13:59:23",9,"//На гоблинскую ярмарку можно даже когда перс на квесте. Просто всечто взял на ярмарке щаберёшь после квеста",162572,null],[172439,"2026-08-25T13:59:45",2,"// я сомневаюсь, что мы уже соберёмся и доиграем как раньше",162572,null],[172440,"2026-08-25T14:00:14",26,";w;//",172439,null],[172441,"2026-08-25T14:00:22",26,"Это реально боль//",162572,null],[172443,"2026-08-25T14:00:52",26,"Вот так и примерзают персы на пожизненно //",162572,null],[172455,"2026-08-25T14:06:58",31,"Ну, я в отпуске, могу играть спокойно//",162572,null],[172457,"2026-08-25T14:07:27",26,"Я безработный, беззаботный школяр на каникулах тоже могу//",162572,null],[172458,"2026-08-25T14:07:55",31,"Коля писал что приболел//",162572,null],[172463,"2026-08-25T15:02:09",17,"/ Ну пишите чето",162572,null],[172464,"2026-08-25T15:02:31",17,"/ Я ини кинул жду замеса. Упал куда то",162572,null],[172465,"2026-08-25T15:04:33",17,"/ А вот прикол",162572,null],[172466,"2026-08-25T15:04:41",17,"/ Это не про меня написано что провалился",162572,null],[172467,"2026-08-25T15:05:52",26,"Ага//",162572,null],[172468,"2026-08-25T15:06:10",26,"Там было предложение провести махыч в owlbear//",162572,null],[172470,"2026-08-25T15:06:46",17,"/ Ну гоу мастер скомандуй",162572,null],[172471,"2026-08-25T15:06:49",17,"/ чё куда",162572,null],[172473,"2026-08-25T15:07:21",17,"— ЗА ЛОРДЕРОН!\n\nДварф бежит с мечом молний на этого гада",162572,null],[173013,"2026-08-25T19:21:39",17,"/ @Shadiq_an @Xerstam_4554 @QURTZZ  продолжим квест или закроем? Я бы продолжил",162572,null],[173014,"2026-08-25T19:21:54",26,"Я сейчас уж спать пойду скоро//",162572,null],[173023,"2026-08-25T19:24:00",17,"/ Ну завтра как?",162572,null],[173037,"2026-08-25T19:28:48",26,"// завтра можно",162572,null],[173046,"2026-08-25T19:32:40",31,"Я завтра буду свободен большую часть дня",162572,null],[173066,"2026-08-25T19:41:08",26,"Тоже самое",173046,null],[173099,"2026-08-25T20:07:29",2,"// я завтра скорее всего занят буду",162572,null],[173108,"2026-08-25T20:13:14",17,"/ Когда будет у тебя время? Чтоб знали и пришли",173099,null],[173226,"2026-08-26T13:14:49",26,"Ну что как у вас дела ,планы?//",162572,null],[173242,"2026-08-26T15:16:05",26,"Завтра у меня с 7 утра и чутка позже будет занято //",162572,null],[173243,"2026-08-26T15:18:57",17,"/ Я щас тут",162572,null],[173244,"2026-08-26T15:23:34",31,"Я тоже тут/ нов роде мастер писал что сегодня не может/",162572,null],[174799,"2026-08-27T15:09:36",2,"// давайте я просто отпущу вас",162572,null],[174803,"2026-08-27T15:13:12",26,":'с//",162572,null],[174806,"2026-08-27T15:19:44",31,"Если нет возможности вести/игиат, то да, лучше отпустить///",174799,null],[174807,"2026-08-27T15:20:01",2,"// тогда отпускаю вас",162572,null],[174809,"2026-08-27T15:20:26",26,"Жумбалака облизнулась и куда-то смылась//",162572,null],[174814,"2026-08-27T15:21:11",31,"Опишешь художественно, или мы просто отмотали время назад до начал квеста?",174807,null],[174823,"2026-08-27T15:22:56",2,"Вы подходите ближе, но глаз не было. Словно это существо уже ушло... Вместе с тем вы видите выход из этого подземелья. Решив, что дальше его может не быть, вы покинули подземелье.",162572,null],[174933,"2026-08-27T17:19:28",17,"/ Ну ладно",162572,null]]);
